<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;class CoupureElectrique extends Model{protected $fillable=['quartier_id','titre','description','type','cause','statut','date_debut','date_fin_estimee','date_fin_reelle','adresse','latitude','longitude','source','actif'];protected function casts():array{return ['actif'=>'boolean','date_debut'=>'datetime','date_fin_estimee'=>'datetime','date_fin_reelle'=>'datetime'];}public function quartier():BelongsTo{return $this->belongsTo(Quartier::class);}public function signalements():HasMany{return $this->hasMany(Signalement::class);}}
